import java.util.*;

public class Solution {
    public static int solve(int[] A, int N, int k) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            if (isDigitValid(A[i], k)) {
                result.add(A[i]);
            }
        }
        return result.size();
    }

    private static boolean isDigitValid(int num, int k) {
        String numStr = Integer.toString(num);
        for (char c : numStr.toCharArray()) {
            if (!Character.isDigit(c) || !k.contains(String.valueOf(c))) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] A = {0, 1, 2, 5};
        int N = 2;
        int k = 21;
        System.out.println(solve(A, N, k)); // Output: 4
    }
}

