public class TetradicPrimes {
    public static boolean isContaindigit(int n) {
        String temp = Integer.toString(n);
        for (int i = 0; i < temp.length(); i++) {
            if (temp.charAt(i) != '0' && temp.charAt(i) != '1' && temp.charAt(i) != '8') {
                return false;
            }
        }
        return true;
    }

    public static boolean ispalindrome(int n) {
        String temp = Integer.toString(n);
        if (temp.equals(temp.reverse())) {
            return true;
        }
        return false;
    }

    public static boolean isTetradic(int n) {
        if (ispalindrome(n)) {
            if (isContaindigit(n)) {
                return true;
            }
        }
        return false;
    }

    public static void printTetradicPrimesLessThanN(int n) {
        boolean[] prime = new boolean[n + 1];
        int p = 2;
        while (p * p <= n) {
            if (prime[p]) {
                for (int i = p * 2; i <= n + 1; i += p) {
                    prime[i] = false;
                }
            }
            p += 1;
        }
        for (int p = 2; p <= n; p++) {
            if (prime[p] && isTetradic(p)) {
                System.out.print(p + " ▁ ");
            }
        }
    }

    public static void main(String[] args) {
        int n = 1000;
        printTetradicPrimesLessThanN(n);
    }
}

