import java.math.BigInteger;
import java.util.stream.LongStream;

public class Staircase {

    public static BigInteger ways(int n) {
        if (n < 3) {
            return BigInteger.ZERO;
        }
        BigInteger c2 = BigInteger.valueOf(0);
        BigInteger c1 = BigInteger.valueOf(n - 3);
        BigInteger l = c1.add(BigInteger.valueOf(1));
        BigInteger s = BigInteger.ZERO;
        BigInteger expC2 = c1.divide(BigInteger.valueOf(2));
        while (expC2.compareTo(c2) >= 0) {
            BigInteger f1 = BigInteger.valueOf(l).multiply(BigInteger.valueOf(c1));
            BigInteger f2 = BigInteger.valueOf(c1).multiply(BigInteger.valueOf(c2));
            BigInteger f3 = BigInteger.valueOf(c2).multiply(BigInteger.valueOf(l));
            s = s.add(f1.divide(f2.multiply(f3)));
            c2 = c1.add(BigInteger.valueOf(1));
            c1 = c1.subtract(BigInteger.valueOf(2));
            l = l.subtract(BigInteger.valueOf(1));
        }
        return s;
    }

    public static void main(String[] args) {
        int N = 7;
        System.out.println(ways(N));
    }
}

