public class FindX {
    public static int findX(int A, int B) {
        int j = 0;
        int x = 0;
        while ((A != 0) || (B != 0)) {
            if ((A & 1) && (B & 1)) {
                x += (1 << j);
            }
            A >>= 1;
            B >>= 1;
            j += 1;
        }
        return x;
    }

    public static void main(String[] args) {
        int A = 2;
        int B = 3;
        int X = findX(A, B);
        System.out.println(" X ▁ = " + X + ", ▁ Sum ▁ = " + (A ^ X) + (B ^ X));
    }
}

