        root.left.left = new Node(29);
        root.left.right = new Node(2);
        root.right.right = new Node(98);
        root.right.left = new Node(1);
        root.right.right.right = new Node(50);
        root.left.left.left = new Node(20);
        findPath(root, k);
    }

    public static void findPath(Node root, int k) {
        ArrayList<Integer> path = new ArrayList<>();
        findPathUtil(root, k, path, 0);
        if (path.size() == 0) {
            System.out.println(-1);
        } else {
            System.out.println(path);
        }
    }

    private static void findPathUtil(Node root, int k, ArrayList<Integer> path, int flag) {
        if (root == null) {
            return;
        }
        if (root.data >= k) {
            flag = 1;
        }
        if (root.left == null && root.right == null) {
            if (flag) {
                System.out.println(" (");
                for (int i = 0; i < path.size(); i++) {
                    System.out.print(path.get(i) + ", ▁ ");
                }
                System.out.println(root.data + ", ▁ ");
            }
            return;
        }
        path.add(root.data);
        findPathUtil(root.left, k, path, flag);
        findPathUtil(root.right, k, path, flag);
        path.remove(path.size() - 1);
    }
}

