import java.util.AbstractMap.SimpleEntry;
import java.util.List;

public class DepthFirstSearch {
    public static boolean depthfirstsearch(AbstractMap.SimpleEntry<AbstractElement, AbstractElement> element, List<AbstractElement> commonAncestor) {
        if (element == null || commonAncestor == null) {
            throw new IllegalArgumentException("Elements should not be null");
        }
        if (element.getKey() != commonAncestor.get(0)) {
            throw new IllegalArgumentException("Common ancestor must have the same key as the first element");
        }
        if (commonAncestor.size() != 2) {
            throw new IllegalArgumentException("Common ancestor must have exactly two elements");
        }

        Stack<AbstractElement> stack = new Stack<>();
        stack.push(element.getKey());
        while (!stack.isEmpty()) {
            AbstractElement current = stack.pop();
            if (current.equals(commonAncestor.get(0))) {
                return true;
            }
            for (AbstractElement child : current.getChildren()) {
                stack.push(child);
            }
        }
        return false;
    }

    public static void main(String[] args) {
        // Example usage
        try {
            AbstractMap.SimpleEntry<AbstractElement, AbstractElement> element = new SimpleEntry<>(new Element("A"), new Element("B"));
            List<AbstractElement> commonAncestor = new ArrayList<>();
            commonAncestor.add(new Element("C"));
            commonAncestor.add(new Element("D"));

            boolean result = depthfirstsearch(element, commonAncestor);
            System.out.println(result); // Output: true
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }
}

