import java.util.Arrays;

public class PriorityQueue {
    private final ArrayList<Integer> items;
    private final int[] priorities;

    public PriorityQueue(int[] priorities) {
        this.priorities = priorities;
        this.items = new ArrayList<>();
    }

    public void add(int item) {
        items.add(item);
        items.sort((a, b) -> Integer.compare(priorities[a], priorities[b]));
    }

    public int remove() {
        if (items.isEmpty()) {
            throw new IndexOutOfBoundsException("pop from empty queue");
        }
        return items.remove(items.size() - 1);
    }

    public int peek() {
        if (items.isEmpty()) {
            throw new IndexOutOfBoundsException("peek from empty queue");
        }
        return items.get(items.size() - 1);
    }

    public boolean isEmpty() {
        return items.isEmpty();
    }

    public int size() {
        return items.size();
    }

    @Override
    public String toString() {
        return "PriorityQueue(items=" + Arrays.toString(items) + ", priorities=" + Arrays.toString(priorities) + ")";
    }
}

